1	// A runner for tests: each turn plays the next script of agent events through
2	// the same interface as the CLI runner. A { type: 'wait' } step holds the turn
3	// until the test calls release(). queue(...scripts) adds scripts for later turns.
4	
5	export function createFakeRunner(scripts = []) {
6	  const turns = [];
7	  let release = () => {};
8	
9	  return {
10	    turns,
11	    release: () => release(),
12	    queue: (...more) => { scripts.push(...more); },
13	    turn(turn) {
14	      turns.push(turn);
15	      const script = scripts.shift() ?? [{ type: 'text', text: 'Done.' }];
16	      let stopped = false;
17	      const gate = new Promise(resolve => { release = resolve; });
18	      const done = (async () => {
19	        turn.onEvent({ type: 'init' });
20	        for (const step of script) {
21	          await new Promise(resolve => setImmediate(resolve));
22	          if (stopped) return { ok: false, stopped: true };
23	          if (step.type === 'wait') { await gate; continue; }
24	          if (step.type === 'fail') return { ok: false, error: step.error };
25	          turn.onEvent(step);
26	        }
27	        if (stopped) return { ok: false, stopped: true };
28	        return { ok: true, costUsd: 0 };
29	      })();
30	      return { done, stop() { stopped = true; release(); } };
31	    },
32	  };
33	}
